   130	    private static final class LongestStageOnFinish extends KeyedProcessFunction<Long, Tuple3<Long, Long, Boolean>, Tuple2<Long, Long>> {
   131	        private final long gapMillis;
   132	
   133	        private transient ValueState<Long> maxStageCount;
   134	        private transient ValueState<Long> finishTimeMillis;
   135	        private transient ValueState<Long> lastObservedEventTimeMillis;
   136	        private transient ValueState<Boolean> emitted;
   137	
   138	        private LongestStageOnFinish(long gapSeconds) {
   139	            this.gapMillis = gapSeconds * 1000L;
   140	        }
   141	
   142	        @Override
   143	        public void open(Configuration parameters) {
   144	            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Types.LONG));
   145	            finishTimeMillis = getRuntimeContext().getState(new ValueStateDescriptor<>("finishTimeMillis", Types.LONG));
   146	            lastObservedEventTimeMillis = getRuntimeContext().getState(new ValueStateDescriptor<>("lastObservedEventTimeMillis", Types.LONG));
   147	            emitted = getRuntimeContext().getState(new ValueStateDescriptor<>("emitted", Types.BOOLEAN));
   148	        }
   149	
   150	        @Override
   151	        public void processElement(Tuple3<Long, Long, Boolean> value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
   152	            Boolean alreadyEmitted = emitted.value();
   153	            if (alreadyEmitted != null && alreadyEmitted) {
   154	                return;
   155	            }
   156	
   157	            Long lastSeen = lastObservedEventTimeMillis.value();
   158	            if (lastSeen == null || value.f1 > lastSeen) {
   159	                lastObservedEventTimeMillis.update(value.f1);
   160	            }
   161	
   162	            if (value.f2) {
   163	                Long currentFinish = finishTimeMillis.value();
   164	                if (currentFinish == null || value.f1 > currentFinish) {
   165	                    finishTimeMillis.update(value.f1);
   166	                }
   167	            } else {
   168	                Long currentMax = maxStageCount.value();
   169	                if (currentMax == null || value.f1 > currentMax) {
   170	                    maxStageCount.update(value.f1);
   171	                }
   172	            }
   173	
   174	            maybeEmit(ctx, out);
   175	        }
   176	
   177	        @Override
   178	        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
   179	            maybeEmit(ctx, out);
   180	        }
   181	
   182	        private void maybeEmit(Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
   183	            Boolean alreadyEmitted = emitted.value();
   184	            if (alreadyEmitted != null && alreadyEmitted) {
   185	                return;
   186	            }
   187	
   188	            Long finish = finishTimeMillis.value();
   189	            if (finish == null) {
   190	                return;
   191	            }
   192	
   193	            Long lastSeen = lastObservedEventTimeMillis.value();
   194	            if (lastSeen == null) {
   195	                lastSeen = finish;
   196	            }
   197	
   198	            long candidateEmitTime = finish + gapMillis;
   199	            if (lastSeen >= candidateEmitTime) {
   200	                Long max = maxStageCount.value();
   201	                out.collect(Tuple2.of(ctx.getCurrentKey(), max == null ? 0L : max));
   202	                emitted.update(true);
   203	            } else {
   204	                ctx.timerService().registerEventTimeTimer(candidateEmitTime);
   205	            }
   206	        }
   207	    }
